  "sh.your_account": { pt: "A sua conta", en: "Your account", zh: "您的账户", fr: "Votre compte" },
  "sh.plan.intro": { pt: "Profissionais e empresas têm {days} dias grátis. Depois: profissionais {provider} por mês, empresas e Lojas {business} por mês. Sem pagamento, o perfil deixa de aparecer aos clientes (não é apagado) e volta a aparecer quando o pagamento é confirmado.", en: "Professionals and businesses get {days} free days. After that: professionals {provider} per month, businesses and Shops {business} per month. Without payment, the profile stops being shown to customers (it is not deleted) and shows again once the payment is confirmed.", zh: "专业人士和企业可享受 {days} 天免费期。之后：专业人士每月 {provider}，企业和商店每月 {business}。未付款时，资料将不再向客户展示（不会被删除），付款确认后重新展示。", fr: "Les professionnels et entreprises ont {days} jours gratuits. Ensuite : professionnels {provider} par mois, entreprises et Boutiques {business} par mois. Sans paiement, le profil n'est plus montré aux clients (il n'est pas supprimé) et réapparaît une fois le paiement confirmé." },
  "sh.plan.none": { pt: "Ainda não tem perfil profissional, empresa nem Loja.", en: "You don't have a professional profile, business or Shop yet.", zh: "您还没有专业资料、企业或商店。", fr: "Vous n'avez pas encore de profil professionnel, d'entreprise ou de Boutique." },
