  "sh.com.short": { pt: "Comissões", en: "Commissions", zh: "佣金", fr: "Commissions" },
  "sh.com.title": { pt: "Comissões das vendas", en: "Sales commissions", zh: "销售佣金", fr: "Commissions sur les ventes" },
  "sh.com.intro": { pt: "Publicar anúncios é grátis. Quando vende, paga à plataforma {pct}% do valor da venda, em {days} dias. Com comissões em atraso não pode publicar anúncios novos.", en: "Posting listings is free. When you sell, you pay the platform {pct}% of the sale value within {days} days. With overdue commissions you cannot post new listings.", zh: "发布广告免费。成交后，您需在 {days} 天内向平台支付成交金额的 {pct}%。有逾期佣金时不能发布新广告。", fr: "Publier des annonces est gratuit. Quand vous vendez, vous payez à la plateforme {pct}% du montant de la vente dans les {days} jours. Avec des commissions en retard, vous ne pouvez pas publier de nouvelles annonces." },
