  "sh.pa.need_day": { pt: "Escolha pelo menos um dia de pagamentos.", en: "Choose at least one payment day.", zh: "请至少选择一个付款日。", fr: "Choisissez au moins un jour de paiement." },
  "sh.pa.saved": { pt: "Definições guardadas.", en: "Settings saved.", zh: "设置已保存。", fr: "Paramètres enregistrés." },
  "sh.pa.why_reject": { pt: "Porque não confirma? (o comprador vai ler)", en: "Why are you not confirming? (the buyer will read this)", zh: "为什么不确认？（买家会看到）", fr: "Pourquoi ne confirmez-vous pas ? (l'acheteur le lira)" },
  "sh.pa.confirm_q": { pt: "Confirma que recebeu {amount} de {name} ({ref})? O vendedor é avisado para enviar.", en: "Do you confirm you received {amount} from {name} ({ref})? The seller will be told to ship.", zh: "确认已收到 {name}（{ref}）的 {amount}？系统将通知卖家发货。", fr: "Confirmez-vous avoir reçu {amount} de {name} ({ref}) ? Le vendeur sera prévenu d'expédier." },
  "sh.pa.confirmed": { pt: "Pagamento confirmado: o dinheiro fica guardado e o vendedor foi avisado.", en: "Payment confirmed: the money is held and the seller has been notified.", zh: "付款已确认：款项已代管，并已通知卖家。", fr: "Paiement confirmé : l'argent est retenu et le vendeur a été prévenu." },
  "sh.pay_rejected": { pt: "Pagamento recusado.", en: "Payment rejected.", zh: "付款已拒绝。", fr: "Paiement refusé." },
  "sh.pa.batch_q": { pt: "Juntar todos os pedidos novos num lote e descarregar o ficheiro para o banco?", en: "Group all new requests into a batch and download the file for the bank?", zh: "将所有新申请合并为一批并下载银行文件？", fr: "Regrouper toutes les nouvelles demandes en un lot et télécharger le fichier pour la banque ?" },
  "sh.pa.batch_done": { pt: "Lote criado e ficheiro descarregado. Depois de pagar no banco, carregue em «Marcar lote como pago».", en: "Batch created and file downloaded. After paying at the bank, tap “Mark batch as paid”.", zh: "批次已创建，文件已下载。在银行付款后，请点击“将批次标记为已付”。", fr: "Lot créé et fichier téléchargé. Après avoir payé à la banque, touchez « Marquer le lot comme payé »." },
  "sh.pa.paid_q": { pt: "Confirma que pagou {n} levantamento(s), total {total}? Referência do lote no banco (opcional):", en: "Do you confirm you paid {n} withdrawal(s), total {total}? Bank batch reference (optional):", zh: "确认已支付 {n} 笔提现，共 {total}？银行批次参考号（可选）：", fr: "Confirmez-vous avoir payé {n} retrait(s), total {total} ? Référence du lot bancaire (facultatif) :" },
  "sh.pa.paid_done": { pt: "Levantamentos marcados como pagos. Os vendedores foram avisados.", en: "Withdrawals marked as paid. The sellers have been notified.", zh: "提现已标记为已付。已通知卖家。", fr: "Retraits marqués comme payés. Les vendeurs ont été prévenus." },
  "sh.pa.reject_q": { pt: "Porque não faz este levantamento? (o vendedor vai ler; o dinheiro volta ao saldo dele)", en: "Why won't you make this withdrawal? (the seller will read this; the money goes back to their balance)", zh: "为什么不处理这笔提现？（卖家会看到；款项将退回其余额）", fr: "Pourquoi n'effectuez-vous pas ce retrait ? (le vendeur le lira ; l'argent revient à son solde)" },
  "sh.pa.rejected": { pt: "Levantamento recusado; o dinheiro voltou ao saldo do vendedor.", en: "Withdrawal rejected; the money went back to the seller's balance.", zh: "提现已拒绝；款项已退回卖家余额。", fr: "Retrait refusé ; l'argent est revenu au solde du vendeur." },
  "sh.pa.release_q": { pt: "Libertar à força o dinheiro de uma encomenda (só sem reclamação aberta). Número da encomenda (ex.: E-1001) ou o código interno:", en: "Force-release the money of an order (only with no open complaint). Order number (e.g. E-1001) or internal code:", zh: "强制放款某订单的款项（仅限无未结投诉）。订单编号（例如 E-1001）或内部代码：", fr: "Forcer le déblocage de l'argent d'une commande (uniquement sans réclamation ouverte). Numéro de la commande (ex. : E-1001) ou code interne :" },
  "sh.pa.why": { pt: "Porquê? (fica registado)", en: "Why? (this is recorded)", zh: "原因？（将被记录）", fr: "Pourquoi ? (c'est enregistré)" },
  "sh.pa.order_not_found": { pt: "Encomenda não encontrada.", en: "Order not found.", zh: "未找到该订单。", fr: "Commande introuvable." },
  "sh.pa.released": { pt: "Dinheiro libertado para o saldo do vendedor.", en: "Money released to the seller's balance.", zh: "款项已放入卖家余额。", fr: "Argent débloqué vers le solde du vendeur." },
  "sh.pa.intro": { pt: "O comprador paga ao Huambo Online; o dinheiro fica guardado até ele confirmar que recebeu. Depois passa para o saldo do vendedor, que pede o levantamento.", en: "The buyer pays Huambo Online; the money is held until they confirm receipt. Then it goes to the seller's balance, who requests the withdrawal.", zh: "买家向 Huambo Online 付款；款项代管至买家确认收货，然后转入卖家余额，由卖家申请提现。", fr: "L'acheteur paie Huambo Online ; l'argent est retenu jusqu'à ce qu'il confirme la réception. Ensuite, il va au solde du vendeur, qui demande le retrait." },
  "sh.pa.held": { pt: "Dinheiro guardado (à espera de entrega)", en: "Money held (waiting for delivery)", zh: "代管款项（等待送达）", fr: "Argent retenu (en attente de livraison)" },
