  "sh.dl.title": { pt: "🚚 Entregas", en: "🚚 Delivery", zh: "🚚 配送", fr: "🚚 Livraison" },
  "sh.dl.to_set": { pt: "para definir as suas entregas.", en: "to set up your delivery options.", zh: "以设置您的配送方式。", fr: "pour configurer vos options de livraison." },
  "sh.dl.intro": { pt: "Diga aos clientes como podem receber as compras. Estas regras valem para os seus produtos da Loja: o carrinho calcula sozinho o preço da entrega. Também aparecem nos seus anúncios, produtos e na sua página de vendedor.", en: "Tell customers how they can receive their purchases. These rules apply to your Shop products: the cart works out the delivery price automatically. They are also shown on your listings, products and seller page.", zh: "告诉顾客如何收到所购商品。这些规则适用于您在商店中的商品：购物车会自动计算配送费。它们也会显示在您的广告、商品和卖家页面上。", fr: "Indiquez aux clients comment ils peuvent recevoir leurs achats. Ces règles s'appliquent aux produits de votre Boutique : le panier calcule automatiquement le prix de livraison. Elles apparaissent aussi sur vos annonces, produits et page de vendeur." },
  "sh.dl.state_set": { pt: "As suas regras de entrega estão ativas.", en: "Your delivery rules are active.", zh: "您的配送规则已生效。", fr: "Vos règles de livraison sont actives." },
  "sh.dl.state_unset": { pt: "Ainda sem regras: a entrega ou o levantamento é combinado com cada cliente, sem preço calculado.", en: "No rules yet: delivery or pickup is arranged with each customer, with no price worked out.", zh: "尚未设置规则：配送或自取需与每位顾客单独商定，不自动计算价格。", fr: "Pas encore de règles : la livraison ou le retrait se convient avec chaque client, sans prix calculé." },
  "sh.dl.pickup_on": { pt: "Levantamento no local (o cliente vem buscar)", en: "Pickup (the customer collects)", zh: "到店自取（顾客自行取货）", fr: "Retrait (le client vient chercher)" },
