// --- Páginas longas: Devoluções e Apagar conta (inglês e mandarim; o português vem do core) ---
type InfoLang = "en" | "zh" | "fr";
function contactLineIn(lang: InfoLang, email?: string | null): string {
  const e = (email ?? "").trim();
  const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);
  if (lang === "fr") return ok ? `Vous pouvez nous contacter par e-mail à ${e}.` : "Vous pouvez nous contacter depuis votre compte (Compte → Aide) ou en signalant le contenu concerné.";
  if (lang === "en") return ok ? `You can contact us by e-mail at ${e}.` : "You can contact us through your account (Account → Help) or by reporting the content concerned.";
  return ok ? `您可以发送电子邮件至 ${e} 联系我们。` : "您可以通过您的账户（账户 → 帮助）联系我们，或举报相关内容。";
}

/** Página em francês, a partir das traduções das páginas de informação. */
function frPageIn(slug: "apagar-conta" | "devolucoes", c: string): InfoPage {
  const p = SV_INFO_PAGES.fr[slug];
  return { slug, title: p.title, updated: LEGAL_UPDATED, intro: p.intro,
    sections: p.sections.map(s => ({ title: s.title, paragraphs: s.paragraphs.map(x => x === "{contact}" ? c : x) })) };
}

/** «Como apagar a minha conta» em inglês, mandarim ou francês. */
export function deleteAccountPageIn(lang: InfoLang, email?: string | null): InfoPage {
  const c = contactLineIn(lang, email);
  if (lang === "fr") return frPageIn("apagar-conta", c);
  if (lang === "en") return {
    slug: "apagar-conta", title: "How to delete my account", updated: LEGAL_UPDATED,
    intro: "You can delete your Huambo Online account at any time, on the Website or in the APP.",
    sections: [
      { title: "Steps", paragraphs: [
        "1. Sign in to your account (Website or APP).",
        "2. Open “Your account”.",
        "3. At the bottom of the page, under “Delete account”, type ELIMINAR and confirm."] },
      { title: "What is deleted", paragraphs: [
        "The account, the profile, listings, products, saved items, saved searches, notifications and the data linked to the account.",
        "Reviews you left for other people and messages already sent may be deleted or kept without your name."] },
      { title: "Can't sign in?", paragraphs: [
        "Use “I forgot my password” on the sign-in page to recover access, then delete the account.", c] }
    ]
  };
  return {
    slug: "apagar-conta", title: "如何删除我的账户", updated: LEGAL_UPDATED,
    intro: "您可以随时在网站或 APP 上删除您的 Huambo Online 账户。",
    sections: [
      { title: "步骤", paragraphs: [
        "1. 登录您的账户（网站或 APP）。",
        "2. 打开“您的账户”。",
        "3. 在页面底部的“删除账户”处，输入 ELIMINAR 并确认。"] },
      { title: "会删除哪些内容", paragraphs: [
        "账户、个人资料、广告、商品、收藏、保存的搜索、通知以及与账户相关的数据。",
        "您给他人的评价和已发送的消息可能会被删除，或保留但不再显示您的姓名。"] },
      { title: "无法登录？", paragraphs: [
        "请在登录页面使用“忘记密码”恢复访问，然后删除账户。", c] }
    ]
  };
}

/** «Devoluções e reembolsos» em inglês, mandarim ou francês. */
export function returnsPageIn(lang: InfoLang, email?: string | null): InfoPage {
  const c = contactLineIn(lang, email);
  if (lang === "fr") return frPageIn("devolucoes", c);
  if (lang === "en") return {
    slug: "devolucoes", title: "Returns and refunds", updated: LEGAL_UPDATED,
    intro: "How to request a return, refund or exchange for an order placed in the Huambo Online Shop, and what happens at each step.",
    sections: [
      { title: "Listings: the item must match the listing", paragraphs: [
        "Whoever posts a listing declares that the description, photos and price match the item, including defects.",
        "If you bought or rented and the item has a hidden defect, is different from the description, is a different item or has missing parts, open the listing and tap “The item does not match the listing” (up to 7 days after the deal).",
        "Choose what you want: exchange, return and refund, or refund. The owner has 3 days to reply; if they decline or don't reply, ask the administration to decide. Complaints appear on this page."] },
      { title: "1. When can I ask", paragraphs: [
        "For a Shop order you have already paid for or received, up to 14 days after delivery.",
        "Reasons: not received, arrived damaged or broken, different from the listing, wrong item (model, size, colour) or missing items.",
        "If the order is still “Pending”, you don't need a request: tap “Cancel”."] },
      { title: "2. What can I ask for", paragraphs: [
        "Refund: the seller gives you the money back (all or part).",
        "Return and refund: you return the item to the seller and they give you the money back.",
        "Exchange: the seller sends you another identical item in good condition."] },
      { title: "3. How to ask", paragraphs: [
        "Open “Orders”, choose the order and tap “Request a return or refund”.",
        "Choose the reason, explain what happened and attach up to 4 photos. The photos stay private: only the seller and the administration can see them.",
        "Follow everything in “Returns and refunds”. Each step sends a notification to the other person."] },
      { title: "4. What the seller does", paragraphs: [
        "Accepts the request or declines it, explaining why.",
        "If they accept a return, agree through messages where to deliver the item. When they receive it, they confirm and refund the money.",
        "When they refund the money, they tap “I have refunded the money” and the buyer confirms receipt."] },
      { title: "5. If you can't agree", paragraphs: [
        "If the seller declines, you can call the administration right away. If someone does not reply within 3 days, either of you can call the administration.",
        "The administration reviews the request, the messages and the photos, and decides: refund (all or part), return, exchange or rejection. The decision is recorded.",
        "Anyone who does not comply with a decision may have their account suspended."] },
      { title: "6. Paid and cancelled order", paragraphs: [
        "If the order was already paid and was cancelled, the refund request opens automatically: the seller must return all the money.",
        "With protected payment, it is Huambo Online that refunds the money still held: enter your IBAN or Multicaixa Express number in the request."] },
      { title: "7. How the money arrives", paragraphs: [
        "For purchases paid to the seller (on delivery, bank transfer or Multicaixa Express), Huambo Online does not hold the money: the refund is made by the seller, by the same payment method, unless the two agree otherwise.",
        "For purchases with protected payment, the money is held by Huambo Online until you confirm receipt. While it is held, the refund is made by Huambo Online. After it has been released to the seller, the seller makes the refund.",
        "Keep the payment and refund receipts: the administration may ask for them."] },
      { title: "8. Deals outside the Shop", paragraphs: [
        "In classified listings (sale, exchange, rental) the deal is made directly between the people, but the conformity guarantee applies: if the item does not match the listing, use “The item does not match the listing” on the listing page (see above). For other problems, use “Report” and the administration will review it."] },
      { title: "9. Contact", paragraphs: [c] }
    ]
  };
  return {
    slug: "devolucoes", title: "退货与退款", updated: LEGAL_UPDATED,
    intro: "如何为在 Huambo Online 商店下的订单申请退货、退款或换货，以及每一步会发生什么。",
    sections: [
      { title: "广告：物品必须与广告相符", paragraphs: [
        "发布广告的人声明描述、照片和价格与物品相符，包括瑕疵。",
        "如果您购买或租用的物品有隐藏缺陷、与描述不符、是另一件物品或缺少部件，请打开该广告并点击“物品与广告不符”（交易后 7 天内）。",
        "选择您的诉求：换货、退货退款或仅退款。物主有 3 天时间回复；如果拒绝或未回复，请让管理员裁决。投诉会显示在本页面。"] },
      { title: "1. 何时可以申请", paragraphs: [
        "对于已付款或已收到的商店订单，可在送达后 14 天内申请。",
        "原因：未收到、到货损坏或破碎、与广告不符、物品错误（型号、尺寸、颜色）或缺少物品。",
        "如果订单仍为“待处理”，无需申请：直接点击“取消”。"] },
      { title: "2. 可以申请什么", paragraphs: [
        "退款：卖家将钱退还给您（全部或部分）。",
        "退货退款：您将物品退回给卖家，卖家将钱退还给您。",
        "换货：卖家给您寄一件相同且完好的物品。"] },
      { title: "3. 如何申请", paragraphs: [
        "打开“订单”，选择订单并点击“申请退货或退款”。",
        "选择原因，说明发生了什么，并附上最多 4 张照片。照片保密：只有卖家和管理员可以查看。",
        "在“退货与退款”中跟进全部进度。每一步都会通知对方。"] },
      { title: "4. 卖家要做什么", paragraphs: [
        "接受申请，或说明理由后拒绝。",
        "如果接受退货，请通过消息商定交还物品的地点。卖家收到后确认并退款。",
        "退款后，卖家点击“我已退款”，由买家确认收款。"] },
      { title: "5. 如果无法达成一致", paragraphs: [
        "如果卖家拒绝，您可以立即请管理员介入。如果有人 3 天内未回复，任何一方都可以请管理员介入。",
        "管理员会查看申请、消息和照片，并作出裁决：退款（全部或部分）、退货、换货或驳回。裁决会被记录。",
        "不遵守裁决的人可能会被暂停账户。"] },
      { title: "6. 已付款并取消的订单", paragraphs: [
        "如果订单已付款后被取消，退款申请会自动发起：卖家必须退还全部款项。",
        "使用受保护付款时，仍在代管中的款项由 Huambo Online 退还：请在申请中填写您的 IBAN 或 Multicaixa Express 号码。"] },
      { title: "7. 退款如何到账", paragraphs: [
        "对于直接付给卖家的购买（货到付款、银行转账或 Multicaixa Express），Huambo Online 不代管款项：退款由卖家通过原付款方式退还，双方另有约定的除外。",
        "对于使用受保护付款的购买，款项由 Huambo Online 代管，直至您确认收货。代管期间，退款由 Huambo Online 退还；款项转给卖家后，则由卖家退款。",
        "请保留付款和退款凭证：管理员可能会要求提供。"] },
      { title: "8. 商店以外的交易", paragraphs: [
        "在分类广告（出售、交换、出租）中，交易直接在双方之间进行，但适用相符保证：如果物品与广告不符，请在广告页面使用“物品与广告不符”（见上文）。其他问题请使用“举报”，由管理员处理。"] },
      { title: "9. 联系方式", paragraphs: [c] }
    ]
  };
}
